    public partial class CodeGenerator
{
        private void GenerateStatement(ASTNode node)
        {
            // 让随后生成的每条指令带上源码行号（语义见 CodeGeneratorBase.CurrentSourceLine）：
            // 它是产物里 `; N: <原文>` 注释的来源，汇编器再读回 `Instruction.SourceLine`
            // ⇒ 链接期/语义期报错才给得出**行列号**（否则只能报个名字）。
            //
            // ⚠ 这一句此前**写不了** —— C 的 `ASTNode` 是个空基类，41 个节点类一个位置字段都没有。
            //   已给基类补上 `Line`/`Column`，并收在**语句入口** `Parser.ParseStatement()` 一处填
            //   （改名前是那个方法的主体，包一层就覆盖了全部 36 个 return）。
            //   判据 `> 0`：没填的节点是 0，置 0 会把上一句的行号冲掉。
            if (node.Line > 0)
            {
                // 两个都设，分工见 `ASTNode.Line`/`OriginalLine`：
                //   · `CurrentSourceLine`         → `InstrList.Add` 抄进指令 ⇒ 产物里的 `; N:` 注释
                //                                    （N 必须与 `SourceLines` 同索引）
                //   · `CurrentSourceOriginalLine` → 诊断给人看的行号（`#include` 展开会推移）
                CurrentSourceLine = node.Line;
                CurrentSourceOriginalLine = node.OriginalLine;
                CurrentSourceColumn = node.Column;
            }

            switch (node)
            {
                case Block block:
                    foreach (var s in block.Statements)
                        GenerateStatement(s);
                    break;
                case VariableDecl varDecl:
                    GenerateVariableDecl(varDecl);
                    // **声明时那次"写初值"不算使用**。
                    //
                    // `int never_used = 5;` 生成时会走一次变量访问（把初值存进去），
                    // 而"用到过"的记账挂在 `FormatVarOffset` 上 —— 不在这里擦掉的话，
                    // 每个带初值的局部量都会被当成"用过了"，**整个检查形同虚设**（实测踩到）。
                    //
                    // 这也是 C 编译器自己的分界：`-Wunused-variable` 管的就是
                    // "声明了但没人读"，而"写过却没读"是另一档（`-Wunused-but-set-variable`），
                    // 那一档要区分"死存储"和"有意写但不读"，误报风险大，本版不做。
                    // 声明之后再被写（`x = 1;` 出现在函数体里）会重新记账，所以那种情况仍然算使用。
                    _localRefs.Remove(varDecl.Name);
                    break;
                case IfStatement ifStmt:
                    GenerateIfStatement(ifStmt);
                    break;
                case WhileStatement whileStmt:
                    GenerateWhileStatement(whileStmt);
                    break;
                case DoWhileStatement doWhileStmt:
                    GenerateDoWhileStatement(doWhileStmt);
                    break;
                case ForStatement forStmt:
                    GenerateForStatement(forStmt);
                    break;
                case SwitchStatement switchStmt:
                    GenerateSwitchStatement(switchStmt);
                    break;
                case ReturnStatement returnStmt:
                    GenerateReturnStatement(returnStmt);
                    break;
                case BreakStatement:
                    GenerateBreakStatement();
                    break;
                case ContinueStatement:
                    GenerateContinueStatement();
                    break;
                case GotoStatement gotoStmt:
                    GenerateGotoStatement(gotoStmt);
                    break;
                case LabeledStatement labeledStmt:
                    GenerateLabeledStatement(labeledStmt);
                    break;
                case AsmStatement asmStmt:
                    GenerateAsmStatement(asmStmt);
                    break;
                case ExpressionStatement exprStmt:
                    // ⚠ `ExpressionStatement` 的 `Expression` **可以是 null**，而且这是**正常形态**：
                    //   解析器用 `new ExpressionStatement(null)` 表示「空语句」（`;`），
                    //   `Parser.Statements.cs` 里有 9 处这么造（`for (...);` 这种空循环体、
                    //   `while (...);`、孤立的 `;` 都是）。这里不判空就等于**假设它永远非空** ——
                    //   实测 `Lib/shared/src/basiclib.c` 的 `basic_instr` 里那句
                    //     `for (j = 0; j < nlen && …; j++);`
                    //   一路 NRE：`GenerateExpression(null)` 在第一行读 `node.Line` 就炸，
                    //   而调用方只看到一个 `NullReferenceException` 的**类型名**，
                    //   连是哪个文件哪一行都没有 ⇒ 整个 `basiclib.vml` 重生成不出来。
                    if (exprStmt.Expression != null)
                        GenerateExpression(exprStmt.Expression);
                    break;
                case TryStatement tryStmt:
                    GenerateTryStatement(tryStmt);
                    break;
                case ThrowStatement throwStmt:
                    GenerateThrowStatement(throwStmt);
                    break;
            }
        }

        private void GenerateAsmStatement(AsmStatement asmStmt)
        {
            var code = asmStmt.Code.Trim();

            // ===== 增强 asm: 支持 ${variable} 变量替换 =====
            // "asm(\"SYSCALL #4, ${ch}\")" → LOAD R0 [var_offset]; asm("SYSCALL #4, R0")
            var varSubstitutions = new List<(string varName, int offset, int regNum)>();
            int regIdx = 0;
            int searchStart = 0;
            while (true)
            {
                int dollar = code.IndexOf("${", searchStart);
                if (dollar < 0) break;
                int braceEnd = code.IndexOf("}", dollar + 2);
                if (braceEnd < 0) break;
                string varName = code.Substring(dollar + 2, braceEnd - dollar - 2).Trim();
                // 查找变量
                bool found = variables.TryGetValue(varName, out int offset);
                if (found)
                {
                    varSubstitutions.Add((varName, offset, regIdx));
                    // LOAD variable value into R0..Rn before the asm
                    string memOp = FormatVarOffset(varName);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new Operand(OperandType.REGISTER, regIdx),
                        new Operand(OperandType.MEMORY, memOp) }));
                    // Replace ${varName} with register reference
                    //
                    // ⚠ **必须带 `@` 标记**（v0.96.328）：这里是 C 前端**唯一自己拼寄存器文本**的地方，
                    //   而它拼出来的串会**绕过序列化器**直接进 `asm "..."` 文本（`AddInstruction(OpCode.ASM,
                    //   Imm(code))`），所以 (c) 规则管不到它。裸写 `R0` 的后果与整个 `@` 方案要治的病同源：
                    //   同一行里还有别的寄存器时（`MOVEF F0, [${p}]` → `MOVEF F0, [R0]`）读者要靠"形状"
                    //   去猜谁是谁，而这正是"变量名就叫 f1"那类静默歧义的老路。
                    //   写 `@R0` 之后，规则 (b) 生效、其余裸 token 由标签集裁定，两边都确定。
                    code = code.Substring(0, dollar) + $"@R{regIdx}" + code.Substring(braceEnd + 1);
                    regIdx++;
                    searchStart = dollar + 3; // "@R0" is 3 chars
                }
                else
                {
                    searchStart = braceEnd + 1; // skip unrecognized
                }
            }

            // SYSCALL #N: emit real SYSCALL instruction (not ASM wrapper)
            if (code.StartsWith("SYSCALL #"))
            {
                // Extract number after "SYSCALL #" (handle trailing text like "SYSCALL #4 R0")
                string numStr = code.Substring(8).Trim().Split(',', ' ', ';')[0].TrimStart('#');
                if (int.TryParse(numStr, out int num))
                {
                    instructions.Add(new Instruction(OpCode.SYSCALL, new List<Operand> {
                        new Operand(OperandType.IMMEDIATE, num) }));
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new Operand(OperandType.MEMORY, "R12-4"),
                        new Operand(OperandType.REGISTER, 0) }));
                    return;
                }
            }
            AddInstruction(OpCode.ASM, Imm(code));
        }

        private void GenerateTryStatement(TryStatement tryStmt)
        {
            if (CurrentOptions.IsMCU)
            {
                // MCU: 仅生成 try body，跳过异常处理
                GenerateStatement(tryStmt.Body);
                return;
            }

            string catchLabel = NewLabel("catch");
            string endTryLabel = NewLabel("endtry");

            Emit(OpCode.CATCH, LabelOp(catchLabel));
            GenerateStatement(tryStmt.Body);
            Emit(OpCode.ENDCATCH);
            Emit(OpCode.JMP, LabelOp(endTryLabel));

            AddLabel(catchLabel);
            foreach (var cc in tryStmt.Catches)
            {
                if (cc.VariableName != null)
                {
                    // 分配 catch 变量并存储异常码 (R0)
                    var info = Vars?.AllocLocal(cc.VariableName, 4);
                    if (info != null)
                        variables[cc.VariableName] = info.Offset;
                    variableTypes[cc.VariableName] = StringToExprType(cc.ExceptionType ?? "int");
                    Emit(GetStoreInstruction(variableTypes[cc.VariableName]), Mem(FormatVarOffset(cc.VariableName)), Reg(0));
                }
                GenerateStatement(cc.Body);
                Emit(OpCode.ENDCATCH);
            }
            AddLabel(endTryLabel);
        }

        private void GenerateThrowStatement(ThrowStatement throwStmt)
        {
            if (CurrentOptions.IsMCU) return;

            if (throwStmt.Expression != null)
                GenerateExpression(throwStmt.Expression);
            else
                EmitLoadInt(0);
            Emit(OpCode.THROW, Reg(0));
        }

        private void GenerateSwitchStatement(SwitchStatement switchStmt)
        {
            var emitCaseValues = new List<Action>();
            var caseBodies = new List<Action>();

            foreach (var caseStmt in switchStmt.Cases)
            {
                var capCase = caseStmt;
                emitCaseValues.Add(() => GenerateExpression(capCase.Value));
                caseBodies.Add(() => GenerateBlock(capCase.Body));
            }

            Action? defaultBody = null;
            if (switchStmt.Default != null)
            {
                var capDefault = switchStmt.Default;
                defaultBody = () => GenerateBlock(capDefault.Body);
            }

            Sta!.EmitSwitchCustom(
                () => GenerateExpression(switchStmt.Expression),
                emitCaseValues,
                caseBodies,
                defaultBody,
                fallthrough: true
            );
        }

        private void GenerateVariableDecl(VariableDecl varDecl)
        {
            // VLA: 运行时动态栈分配
            if (varDecl.IsVLA)
            {
                GenerateVLAAllocation(varDecl);
                // VLA 不支持初始化器 — 跳过 initializer 处理
                return;
            }

            if (varDecl.Initializer != null)
            {
                if (varDecl.IsStatic)
                {
                    // static局部变量初始化: 存到data section
                    if (varDecl.Initializer is NumberLiteral numLit)
                    {
                        dataSection[staticLocals[varDecl.Name]] = Convert.ToInt32(numLit.Value);
                    }
                    else if (varDecl.Initializer is ArrayInitializer staticArrInit)
                    {
                        GenerateStaticArrayInit(varDecl, staticArrInit);
                    }
                    else
                    {
                        GenerateExpression(varDecl.Initializer);
                        var storeOp = GetStoreInstruction(StringToExprType(varDecl.Type));
                        instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, staticLocals[varDecl.Name]), new Operand(OperandType.REGISTER, 0) }));
                    }
                }
                else if (varDecl.Initializer is ArrayInitializer arrayInit)
                {
                    // 处理数组初始化
                    GenerateArrayInitialization(varDecl, arrayInit);
                }
                else if (varDecl.Initializer is StringLiteral strArrInit && varDecl.IsArray)
                {
                    // `char h[] = "ABC";` —— 此前**没有这条分支**，整个初始化被静默跳过、
                    // 数组全 0（判据 `ArraySize.HasValue || Initializer is ArrayInitializer`
                    // 对它是双假）。见 GenerateStringArrayInitialization 的注释。
                    GenerateStringArrayInitialization(varDecl, strArrInit);
                }
                else
                {
                    // Check if this is a struct initialization (not a pointer to struct)
                    var stType = ResolveStructType(varDecl.Type);
                    bool isPtrType = varDecl.Type.Contains('*');
                    if (stType != null && !isPtrType)
                    {
                        int structSize = GetTypeSizeFromString(stType);
                        // R9 = destination address
                        string destOffset = FormatVarOffset(varDecl.Name);
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 9), new Operand(OperandType.REGISTER, 12) }));
                        if (destOffset.StartsWith("R12+"))
                        {
                            int off = int.Parse(destOffset.Substring(4));
                            if (off != 0)
                                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 9), new Operand(OperandType.IMMEDIATE, off) }));
                        }
                        else if (destOffset.StartsWith("R12-"))
                        {
                            int off = int.Parse(destOffset.Substring(4));
                            instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 9), new Operand(OperandType.IMMEDIATE, off) }));
                        }

                        if (varDecl.Initializer is FunctionCall funcInit)
                        {
                            int argCount = funcInit.Args.Count;
                            int pad = StructCallPadding(structSize, argCount);

                            // Save destination address (R9) on stack for later POP
                            instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 9) }));

                            // Push dummy padding so callee's param stores don't clobber saved dest
                            int padWords = pad / 4;
                            for (int p = 0; p < padWords; p++)
                                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));

                            // Allocate return struct space on stack
                            instructions.Add(new Instruction(OpCode.SUB, new List<Operand> {
                                new(OperandType.REGISTER, 13), new(OperandType.IMMEDIATE, structSize) }));
                            // R9 = R13 (return space address — will become R0 = hidden ptr)
                            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 9), new Operand(OperandType.REGISTER, 13) }));

                            // Evaluate args left-to-right, saving to R1-R3 (CCv2 register params).
                            // R0 is reserved for the hidden return pointer.
                            int regSlots = Math.Min(argCount, 3); // R1, R2, R3
                            for (int i = 0; i < argCount; i++)
                            {
                                GenerateExpression(funcInit.Args[i]);
                                if (i < regSlots)
                                    instructions.Add(new Instruction(OpCode.MOVE,
                                        new List<Operand> { new Operand(OperandType.REGISTER, 1 + i), new Operand(OperandType.REGISTER, 0) }));
                                else
                                    instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                            }

                            // R0 = hidden return pointer (return space address)
                            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 9) }));

                            // CALL the function
                            instructions.Add(new Instruction(OpCode.CALL, new List<Operand> { new Operand(OperandType.LABEL, funcInit.Name) }));

                            // Clean up extra stack args (beyond R3)
                            int extraArgs = argCount - 3;
                            if (extraArgs > 0)
                                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 13), new Operand(OperandType.IMMEDIATE, extraArgs * 4) }));

                            // R10 = R13 (source = return struct space)
                            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 10), new Operand(OperandType.REGISTER, 13) }));
                            // Restore SP past return struct space + padding
                            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 13), new Operand(OperandType.IMMEDIATE, structSize + pad) }));
                            // POP destination → R9
                            instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, 9) }));

                            // Copy word by word from [R10] to [R9]
                            EmitStructCopy(9, 10, structSize);
                        }
                        else
                        {
                            // R10 = source address
                            GenerateAddressOf(varDecl.Initializer);
                            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 10), new Operand(OperandType.REGISTER, 0) }));

                            // Copy word by word
                            EmitStructCopy(9, 10, structSize);
                        }
                    }
                    else
                    {
                        // 处理普通变量初始化
                        GenerateExpression(varDecl.Initializer);
                        // 存储到局部变量 — 若目标为浮点/双精度/LongLong，先做类型转换
                        var targetType = StringToExprType(varDecl.Type);
                        var sourceType = InferExpressionType(varDecl.Initializer);
                        var storeOp = GetStoreInstruction(targetType);
                        EmitTypeConversion(sourceType, targetType);
                        instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, $"{FormatVarOffset(varDecl.Name)}"), new Operand(OperandType.REGISTER, 0) }));
                    }
                }
            }
        }

        /// <summary>
        /// 生成 VLA (Variable Length Array) 运行时栈分配代码
        /// 变量槽存储指向动态分配内存的指针
        /// </summary>
        private void GenerateVLAAllocation(VariableDecl varDecl)
        {
            if (varDecl.VlaDimensions == null || varDecl.VlaDimensions.Count == 0)
                return;

            int elemSize = GetTypeSize(StringToExprType(varDecl.Type));
            // R0 保存逐维乘积, 用 R1 保存临时值
            // 最终 R0 = total bytes to allocate

            // 第一维: R0 = dim0
            GenerateExpression(varDecl.VlaDimensions[0]);

            // 后续维: R0 *= dimN
            for (int i = 1; i < varDecl.VlaDimensions.Count; i++)
            {
                // 保存 R0 → 压栈
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                GenerateExpression(varDecl.VlaDimensions[i]);  // R0 = dimN
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, 1) }));  // R1 = saved
                instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) }));
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 1) }));
            }

            // R0 = total elements, now multiply by element size
            if (elemSize > 1)
            {
                instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, elemSize) }));
            }

            // SP 对齐到 4 字节
            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) }));
            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.IMMEDIATE, 3) }));
            instructions.Add(new Instruction(OpCode.AND, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.IMMEDIATE, -4) }));  // mask lower 2 bits

            // R13(SP) -= total_bytes → 分配 VLA 空间
            instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 13), new Operand(OperandType.REGISTER, 1) }));

            // 存储 VLA 指针到变量槽
            string offset = FormatVarOffset(varDecl.Name);
            OpCode storeOp = GetStoreInstruction(StringToExprType(varDecl.Type));
            if (offset.StartsWith("R12"))
            {
                instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, offset), new Operand(OperandType.REGISTER, 13) }));
            }
        }

        private void GenerateArrayInitialization(VariableDecl varDecl, ArrayInitializer arrayInit)
        {
            int elemSize = GetTypeSize(StringToExprType(varDecl.Type));
            GenerateArrayInitRecursive(varDecl, arrayInit, elemSize, 0);
        }

        /// <summary>
        /// `char h[] = "ABC";` —— **局部数组 + 字符串字面量初始化**。
        ///
        /// 这条路径此前**完全不存在**。判据 `ArraySize.HasValue || Initializer is
        /// ArrayInitializer` 对它是**双假**：`[]` 靠推断 ⇒ `ArraySize` 为 null；
        /// 初始化器是 `StringLiteral` 而非 `ArrayInitializer`
        /// ⇒ 分支被跳过、**一行初始化代码都不生成、数组静默全 0**。
        /// 实测最小复现：`char h[] = "ABC"; return h[0];` 得 0（应 65）；
        /// 手动逐元素赋值与 `char *h = "ABC"` 两条路都正常 —— 所以问题**专在"初始化"这一步**。
        /// 后果不止"值错"：`Lib/shared/src/convert.c` 的 `itoa_hex` 里有
        /// `char hex[] = "0123456789ABCDEF";`，于是它输出全错、并把栈都搞坏
        /// （实测 `R12(BP)=00000004`、`R13(SP)=FFFFFFF8`）。
        /// </summary>
        private void GenerateStringArrayInitialization(VariableDecl varDecl, StringLiteral strLit)
        {
            int elemSize = GetTypeSize(StringToExprType(varDecl.Type));
            string varOffset = FormatVarOffset(varDecl.Name);
            string s = strLit.Value ?? "";
            // `<=` —— **结尾的 NUL 也要写进去**（C 里 `char h[] = "AB"` 的数组长度是 3）
            for (int i = 0; i <= s.Length; i++)
            {
                // R0 = 数组基址 + i*elemSize
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                    new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                if (varOffset.StartsWith("R12+"))
                {
                    int off = int.Parse(varOffset.Substring(4));
                    if (off != 0)
                        instructions.Add(new Instruction(OpCode.ADD, new List<Operand> {
                            new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, off) }));
                }
                else if (varOffset.StartsWith("R12-"))
                {
                    int off = int.Parse(varOffset.Substring(4));
                    instructions.Add(new Instruction(OpCode.SUB, new List<Operand> {
                        new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, off) }));
                }
                int byteOff = i * elemSize;
                if (byteOff != 0)
                    instructions.Add(new Instruction(OpCode.ADD, new List<Operand> {
                        new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, byteOff) }));

                // 地址先存起来（下面写值要用 R0），与 GenerateArrayInitRecursive 同一套 idiom
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                int ch = i < s.Length ? (int)s[i] : 0;
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                    new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, ch) }));
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, 1) }));

                instructions.Add(new Instruction(elemSize == 1 ? OpCode.MOVEB : OpCode.MOVE, new List<Operand> {
                    new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0) }));
            }
        }

        private int GenerateArrayInitRecursive(VariableDecl varDecl, ASTNode init, int elemSize, int baseOffset)
        {
            if (init is ArrayInitializer arrayInit)
            {
                int offset = baseOffset;
                foreach (var elem in arrayInit.Elements)
                {
                    offset = GenerateArrayInitRecursive(varDecl, elem, elemSize, offset);
                }
                return offset;
            }

            // 单个元素初始化
            var varOffset = FormatVarOffset(varDecl.Name);
            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
            if (varOffset.StartsWith("R12+"))
            {
                int off = int.Parse(varOffset.Substring(4));
                if (off != 0)
                    instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, off) }));
            }
            else if (varOffset.StartsWith("R12-"))
            {
                int off = int.Parse(varOffset.Substring(4));
                instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, off) }));
            }
            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, baseOffset) }));

            // Save address before GenerateExpression overwrites R0
            instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
            GenerateExpression(init);
            instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, 1) }));

            if (elemSize == 1)
                instructions.Add(new Instruction(OpCode.MOVEB, new List<Operand> { new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0) }));
            else
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.MEMORY, "R1"), new Operand(OperandType.REGISTER, 0) }));

            return baseOffset + elemSize;
        }

        private void GenerateStaticArrayInit(VariableDecl varDecl, ArrayInitializer arrayInit)
        {
            string label = staticLocals[varDecl.Name];
            var initValues = new List<object>();
            FlattenArrayInitValues(arrayInit, initValues);
            int arraySize = varDecl.ArraySize ?? initValues.Count;
            /* 与全局数组**同一个构造器**（`BuildArrayData` → `ArrayElemSize`）。
               ⚠ 这里原先算出来的 `isShort`/`isChar` 是**死变量**（注释还写着
               "short/char 也按 4 字节存"）—— 那正是"存储 4 字节 / 下标 1 字节"的成因。 */
            dataSection[label] = BuildArrayData(varDecl.Type, initValues, arraySize);
        }

        private void FlattenArrayInitValues(ASTNode node, List<object> result)
        {
            if (node is ArrayInitializer arrayInit)
            {
                foreach (var elem in arrayInit.Elements)
                {
                    FlattenArrayInitValues(elem, result);
                }
            }
            else if (node is NumberLiteral numLit)
            {
                result.Add(numLit.Value);
            }
            else if (node is StringLiteral strLit)
            {
                // 同 `FlattenArrayInitializer`：**给字符串分配数据段标签**，元素存标签名 ——
                // 直接塞内容会序列化成 `.word abc`（内容当标签名），而那个标签不存在。
                // 两条路各写一份是**刻意**的：它们写进的是两个不同的数据段，
                // 但**这条判据必须一模一样**（见 ConstFold.cs 顶部那段说明）。
                string strLabel = GenerateLabel();
                dataSection[strLabel] = strLit.Value;
                result.Add(strLabel);
            }
            // 常量表达式（`-1`、`1+2`…）—— 同 FlattenArrayInitializer，见 ConstFold.cs：
            // 这条没有的话 `static int d[4] = {0,1,0,-1}` 里的负数会被静默当成 0。
            else if (ConstFold.TryNumber(node, out var folded))
            {
                result.Add(folded!);
            }
            else
            {
                result.Add(0); // fallback for non-constant expressions
            }
        }

        private void GenerateIfStatement(IfStatement ifStmt)
        {
            Sta!.EmitIf(
                () => GenerateExpression(ifStmt.Condition),
                () => GenerateBlock(ifStmt.ThenBranch),
                ifStmt.ElseBranch != null ? () => GenerateBlock(ifStmt.ElseBranch) : null);
        }

        private void GenerateWhileStatement(WhileStatement whileStmt)
        {
            Sta!.EmitWhile(
                () => GenerateExpression(whileStmt.Condition),
                () => GenerateBlock(whileStmt.Body));
        }

        private void GenerateForStatement(ForStatement forStmt)
        {
            System.Action? emitInit = null;
            if (forStmt.Init != null)
            {
                if (forStmt.Init is VariableDecl varDeclInit)
                    emitInit = () => GenerateVariableDecl(varDeclInit);
                else
                    emitInit = () => GenerateExpression(forStmt.Init);
            }

            Sta!.EmitFor(
                emitInit,
                forStmt.Condition != null ? () => GenerateExpression(forStmt.Condition) : null,
                forStmt.Update != null ? () => GenerateExpression(forStmt.Update) : null,
                () => GenerateBlock(forStmt.Body));
        }

        private void GenerateReturnStatement(ReturnStatement returnStmt)
        {
            if (returnStmt.Value != null)
            {
                if (hiddenReturnPtrOffset >= 0)
                {
                    // Struct return by value: copy return struct to caller-allocated space
                    // 1. Get source struct address → R10
                    ASTNode retVal = returnStmt.Value;
                    if (retVal is Identifier)
                        GenerateAddress(retVal);
                    else if (retVal is MemberAccess)
                        GenerateMemberAddress((MemberAccess)retVal);
                    else
                        GenerateAddress(retVal);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 10), new(OperandType.REGISTER, 0) }));
                    // 2. Load hidden return pointer (destination) → R9
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 9), new(OperandType.MEMORY, $"R12+{hiddenReturnPtrOffset}") }));
                    // 3. Copy struct word by word from source to destination
                    int structSize = GetTypeSizeFromString(CurrentFunction.ReturnType);
                    EmitStructCopy(9, 10, structSize);
                    // 4. Return the hidden pointer address in R0 (caller expects this)
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 0), new(OperandType.MEMORY, $"R12+{hiddenReturnPtrOffset}") }));
                }
                else
                {
                    // 生成返回值表达式
                    GenerateExpression(returnStmt.Value);
                    // 结果在 R0 中
                }
            }

            // 跳转到函数末尾的退出代码
            if (!functionEndLabels.TryGetValue(CurrentFunction!.Name, out string? endLabel))
            {
                endLabel = GenerateLabel();
                functionEndLabels[CurrentFunction.Name] = endLabel;
            }
            instructions.Add(new Instruction(OpCode.JMP, new List<Operand> { new Operand(OperandType.LABEL, endLabel) }));
        }

        private void GenerateBreakStatement()
        {
            if (!Sta!.HasLoopLabels)
                throw new CodeGenerationException(ErrorCode.CodeGen_BreakOutsideLoop, "break 语句不在循环或switch内");
            Sta.EmitBreak();
        }

        private void GenerateContinueStatement()
        {
            if (!Sta!.HasLoopLabels)
                throw new CodeGenerationException(ErrorCode.CodeGen_ContinueOutsideLoop, "continue 语句不在循环内");
            Sta.EmitContinue();
        }

        private void GenerateDoWhileStatement(DoWhileStatement doWhileStmt)
        {
            Sta!.EmitDoWhile(
                () => GenerateBlock(doWhileStmt.Body),
                () => GenerateExpression(doWhileStmt.Condition));
        }

        private void GenerateGotoStatement(GotoStatement gotoStmt)
        {
            // 生成跳转到标签的指令
            instructions.Add(new Instruction(OpCode.JMP, new List<Operand> { new(OperandType.LABEL, gotoStmt.Label) }));
        }

        private void GenerateLabeledStatement(LabeledStatement labeledStmt)
        {
            // 生成标签
            labels[labeledStmt.Label] = instructions.Count;
            // 生成标签语句
            GenerateStatement(labeledStmt.Statement);
        }

        /// <summary>
        /// 将字符串类型转换为表达式类型
        /// </summary>
        // 跟踪 typedef 解析深度，防止循环引用导致无限递归
        private HashSet<string>? _typeResolutionStack;

        private ExprType StringToExprType(string type)
        {
            if (string.IsNullOrEmpty(type)) return ExprType.Unknown;

            type = type.ToLower().Trim();

            // Remove qualifiers
            type = type.Replace("const", "").Replace("volatile", "").Replace("restrict", "").Replace("extern", "").Replace("static", "").Trim();
            while (type.Contains("  ")) type = type.Replace("  ", " ");

            // Strip array dimensions to get the base element type
            // e.g., "uint8_t[4][4]" → "uint8_t", "unsigned char[4]" → "unsigned char"
            int arrBracketIdx = type.IndexOf('[');
            if (arrBracketIdx >= 0)
                return StringToExprType(type.Substring(0, arrBracketIdx).Trim());

            // Resolve typedef'd types — 防止循环引用
            if (typeAliases != null && typeAliases.TryGetValue(type, out var resolved))
            {
                _typeResolutionStack ??= new HashSet<string>();
                if (!_typeResolutionStack.Add(type))
                {
                    // 检测到循环 typedef，回退为 Unknown
                    Console.Error.WriteLine($"[WARN] 循环 typedef 引用: {type} → {resolved}");
                    return ExprType.Unknown;
                }
                try { return StringToExprType(resolved); }
                finally { _typeResolutionStack.Remove(type); }
            }

            // Handle pointer types — must be before struct/union/enum checks
            bool isPointer = type.Contains('*');
            if (isPointer)
            {
                string baseType = type.Replace("*", "").Trim();
                ExprType baseExprType = StringToExprType(baseType);

                switch (baseExprType)
                {
                    case ExprType.Char: case ExprType.UnsignedChar:
                        return ExprType.CharPtr;
                    case ExprType.Short: case ExprType.UnsignedShort:
                        return ExprType.ShortPtr;
                    case ExprType.Int: case ExprType.UnsignedInt:
                        return ExprType.IntPtr;
                    case ExprType.Long: case ExprType.UnsignedLong:
                        return ExprType.LongPtr;
                    case ExprType.LongLong: case ExprType.UnsignedLongLong:
                        return ExprType.IntPtr; // 64-bit = 2 registers, use int pointer
                    case ExprType.Float: return ExprType.FloatPtr;
                    case ExprType.Double: return ExprType.DoublePtr;
                    case ExprType.Void: return ExprType.VoidPtr;
                    case ExprType.Struct: return ExprType.IntPtr; // pointer to struct = int-size pointer
                    default: return ExprType.IntPtr;
                }
            }

            // Struct/union/enum types
            if (type.StartsWith("struct ") || type.StartsWith("union "))
                return ExprType.Struct;
            if (type.StartsWith("enum "))
                return ExprType.Int;

            // Handle basic types
            if (type == "void") return ExprType.Void;
            if (type == "char") return ExprType.Char;
            if (type == "short") return ExprType.Short;
            if (type == "int") return ExprType.Int;
            if (type == "long") return ExprType.Long;
            if (type == "long long") return ExprType.LongLong;
            if (type == "float") return ExprType.Float;
            if (type == "double") return ExprType.Double;

            if (type == "unsigned char") return ExprType.UnsignedChar;
            if (type == "unsigned short") return ExprType.UnsignedShort;
            if (type is "unsigned int" or "unsigned") return ExprType.UnsignedInt;
            if (type == "unsigned long") return ExprType.UnsignedLong;
            if (type == "unsigned long long") return ExprType.UnsignedLongLong;
            if (type == "size_t") return ExprType.UnsignedInt;
            if (type == "ssize_t") return ExprType.Int;
            if (type == "wchar_t") return ExprType.UnsignedShort;
            if (type == "char32_t") return ExprType.UnsignedInt;
            if (type is "_Bool" or "bool") return ExprType.Bool;

            if (type == "signed char") return ExprType.Char;
            if (type is "signed short" or "signed short int") return ExprType.Short;
            if (type is "signed int" or "signed") return ExprType.Int;
            if (type is "signed long" or "signed long int") return ExprType.Long;
            if (type is "signed long long" or "signed long long int") return ExprType.LongLong;

            if (type.Contains("unsigned"))
            {
                if (type.Contains("long")) return ExprType.UnsignedLong;
                if (type.Contains("short")) return ExprType.UnsignedShort;
                if (type.Contains("char")) return ExprType.UnsignedChar;
                return ExprType.UnsignedInt;
            }

            if (type.Contains("signed"))
            {
                if (type.Contains("long")) return ExprType.Long;
                if (type.Contains("short")) return ExprType.Short;
                if (type.Contains("char")) return ExprType.Char;
                return ExprType.Int;
            }

            return ExprType.Unknown;
        }

        private static string ExprTypeToString(ExprType type)
        {
            return type switch
            {
                ExprType.Char          => "char",
                ExprType.Short         => "short",
                ExprType.Int           => "int",
                ExprType.Long          => "long",
                ExprType.LongLong      => "long long",
                ExprType.UnsignedChar  => "unsigned char",
                ExprType.UnsignedShort => "unsigned short",
                ExprType.UnsignedInt   => "unsigned int",
                ExprType.UnsignedLong  => "unsigned long",
                ExprType.UnsignedLongLong => "unsigned long long",
                ExprType.Float         => "float",
                ExprType.Double        => "double",
                ExprType.Void          => "void",
                _                      => "int"
            };
        }

        /// <summary>
        /// 推断表达式类型
        /// </summary>
        /// <summary>
        /// 变量的 <see cref="ExprType"/> —— **局部与全局都要看，这是唯一一处判据**。
        ///
        /// ## 为什么必须是一个助手而不是两处各写一遍
        ///
        /// `variableTypes` 只装**局部**变量，全局变量在 `ast.Variables` 里。这个"先查局部、
        /// 再回退全局声明"的口诀原先只有**取标识符值**那一条路写了
        /// （`CodeGenerator.Expressions.cs` 的"优先从 variableTypes 获取，其次从 AST 全局变量声明"），
        /// 而**数组下标**那条路（`InferExpressionType` 的 `ArrayAccess` 分支）只查了 `variableTypes`
        /// 就直接 `return ExprType.Int` —— 于是：
        ///
        /// <code>char g[8];          /* 全局 */
        /// int main() { g[0] = 'A'; if (g[0] == 'A') … }   /* 走的是 MOVE（32 位），不是 MOVEB */</code>
        ///
        /// 按 32 位读写 `char` 数组的后果是**编得过、跑起来值不对**：`g[0]='A'` 之后
        /// `g[0]=='A'` 为 false（32 位读回来的是相邻几个字节拼成的 `0x??????41`）；
        /// 写还会**越界**（`char g[8]` 的 `g[7]` 会写到数组外面 3 个字节）。
        /// 局部数组一直是对的（`variableTypes` 里有），所以这个坑只在全局数组上冒头 ——
        /// 实测四个格子：局部下标读/写 ✓、全局下标读/写 ✗（`.scratch/vmlhost/tests/globchar.c`）。
        /// </summary>
        private ExprType GetVarExprType(string name)
        {
            if (variableTypes.TryGetValue(name, out var t)) return t;
            var globalVar = ast.Variables.FirstOrDefault(v => v.Name == name);
            if (globalVar == null) return ExprType.Int;
            var resolved = StringToExprType(globalVar.Type);
            // 认不出的类型（自定义 struct 之类）**保持原来的 32 位语义** ——
            // 这条回退路径的任务是"修好能认的那部分"，不是顺带改掉认不出的那部分。
            return resolved == ExprType.Unknown ? ExprType.Int : resolved;
        }

        /// <summary>
        /// 声明的类型是不是**指针的数组**（`char *rows[]`）—— 这种形状下数组元素**是指针**。
        ///
        /// ⚠ 必须看**声明原文**：`ExprType` 已经把维度剥掉了，剥完 `char *rows[]`
        /// 与 `char *p` 都是 `CharPtr`，再也分不出哪个是数组。
        ///
        /// ⚠⚠ **维度有两种存法，缺一不可**：解析器对**带显式长度**的数组把维度写进类型串
        /// （`int a[4][4]` → `"int[4][4]"`），而对 `char *rows[]` 这种**不带长度的**，
        /// 类型串只剩 `"char *"`、维度落在 `IsArray` 标志上。只查类型串的话后者判不到
        /// （实测就是这么白跑一轮：判据没命中，`moveb` 照旧）。
        /// </summary>
        private bool DeclaredArrayOfPointers(string name)
        {
            // ① **权威来源**：全局遍历那一刻记下的（那里 `IsArray` 与类型串都还完整）。
            if (arrayOfPointerVars.Contains(name)) return true;

            var (decl, isArray) = DeclaredTypeOf(name);

            if (string.IsNullOrEmpty(decl) || decl.IndexOf('*') < 0) return false;

            // ② 类型串里自带维度（`int *p[4]`）
            int bracket = decl.IndexOf('[');
            if (bracket >= 0) return decl.IndexOf('*') < bracket;

            // ③ 兜底：维度落在 IsArray 上（局部变量走这条）
            return isArray;
        }

        /// <summary>
        /// 变量声明的**原文**类型串与 <c>IsArray</c> —— 局部/形参看 `variableTypeStrings`，
        /// 否则回全局声明表。**只此一份**（`DeclaredArrayOfPointers` 与
        /// <see cref="ElementIsPointer"/> 共用）：两份查法必然漂移，而漂移的症状正是本仓
        /// 反复出现的「同一规则两处实现」。
        /// </summary>
        private (string? Decl, bool IsArray) DeclaredTypeOf(string name)
        {
            if (variableTypeStrings != null && variableTypeStrings.TryGetValue(name, out var local))
                return (local, arrayLocalVars.Contains(name));

            var g = ast.Variables.FirstOrDefault(v => v.Name == name);
            return (g?.Type, g?.IsArray ?? false);
        }

        /// <summary>声明是**指针变量而非数组**（`char *s` / `char **p`）—— 用作下标基址时要取它的**值**。</summary>
        private bool IsPointerDeclName(string name)
        {
            var (decl, _) = DeclaredTypeOf(name);
            return !string.IsNullOrEmpty(decl) && decl.IndexOf('*') >= 0;
        }

        /// <summary>
        /// `x[i]` 的**元素是不是指针** —— 「元素类型」的唯一判据，三处共用
        /// （`InferExpressionType` 定元素类型、`GenerateArrayAddress` 定步长、
        /// 多级下标的**基址取地址还是取值**）。
        ///
        /// 三种形状都算：
        ///   · `T *x[]`（指针数组）—— 元素就是那个指针（`DeclaredArrayOfPointers`）
        ///   · `T **x`（指针的指针）—— `x[i]` 解出来仍是指针
        ///   · `T *x` / `T x[]` / `T x` —— **不是**（`x[i]` 解一层引用就是元素本身）
        ///
        /// ⚠ 少了第二条时，`char **fr` 的 `fr[i]` 会被判成 `char` ⇒ 按**字节**读指针
        /// （`moveb`+`sextb`），只读到地址最低一个字节。实测症状就是
        /// 「nyancat 的三帧只发出三个 ESC，着色字符一个没读到」——
        /// 帧数组、`argv`、curses 的行缓冲全是这个形状。
        /// </summary>
        private bool ElementIsPointer(string name)
        {
            if (DeclaredArrayOfPointers(name)) return true;

            var (decl, _) = DeclaredTypeOf(name);
            if (string.IsNullOrEmpty(decl)) return false;

            int stars = 0;
            foreach (var ch in decl) if (ch == '*') stars++;
            return stars >= 2;                       // `T **x`（`T *x[]` 已被上面那条收走）
        }

        /// <summary>
        /// 声明的**数组维度数**（`char *bs[2][3]` → 2；`char *rows[]` → 1；**不是数组** → 0）。
        ///
        /// ## 为什么需要它：**数组的下标不解引用，指针的下标才解**
        ///
        /// `InferExpressionType` 里那条"多级下标要按级数继续解引用"的规则，原本是照
        /// `T **p` 写的（`p[i]` 解一层、`p[i][j]` 再解一层）。但**数组不是指针**：
        /// `char *bs[2][3]` 的 `bs[i]` 走掉一个**维度**（`vml` 里是 +i*4 的地址运算），
        /// 元素类型始终是 `char *`；照指针那条规则再解一层，`bs[i][j]` 就被判成 `char`
        /// ⇒ **最后一个取值按 1 字节读，而且基址取成了"元素里存的那个指针"**。
        ///
        /// 实测（`probe3.c`，本仓 `scripts/vml-c-probe/cases/33-mdim-pointer-array.c`）：
        /// `static char *bs[2][3] = {{"a1","a2","a3"},{"b1","b2","b3"}};` 读 `bs[0][0]`
        /// 得到 **97（`'a'`）** 而不是那个指针；`%s` 打印出来是**空串**。
        /// 一维的 `char *rows[]` 一直是对的（它只解一层，恰好落在正确的一侧），
        /// **二维才露馅** —— 而老程序里的字符串表（`sl` 的整车图形、菜单、`argv` 那类）
        /// 大量是二维的。
        ///
        /// 三种形状都要能答对，所以按"**有几个下标走维度**"算：
        ///   · `char *bs[2][3]`：dims=2，`bs[i][j]` 的参数数(2) 不超出维度 ⇒ **不解引用**
        ///   · `char *rows[]`（dims=1）与一维下标：dims 已经把第一个下标吃掉 ⇒ 不解引用
        ///   · `char **p`（dims=0，是指针不是数组）：每个下标解一层 ⇒ 参数数减 1 层
        /// </summary>
        private int DeclaredArrayDims(string name)
        {
            // ① 局部数组：解析时按类型串抽出来的维度（`localArrayDimensions`）
            if (localArrayDimensions.TryGetValue(name, out var localDims) && localDims is { Count: > 0 })
                return localDims.Count;

            // ② 全局数组：**声明节点上的 `Dimensions` 才是权威的** ——
            //    `ParseVariableDecl` 把维度记在这里，而**不写进类型串**
            //    （`char *bs[2][3]` 的 `Type` 只有 `"char *"`，看 `[` 是数不出来的）。
            var global = ast.Variables.FirstOrDefault(v => v.Name == name);
            if (global?.Dimensions is { Count: > 0 }) return global.Dimensions.Count;

            // ③ 兜底：类型串里带维度的写法（`int *p[4]`）
            var (decl, isArray) = DeclaredTypeOf(name);
            int fromText = 0;
            if (!string.IsNullOrEmpty(decl))
                foreach (var ch in decl) if (ch == '[') fromText++;
            if (fromText > 0) return fromText;

            return isArray ? 1 : 0;      // 不带长度的数组（`char *rows[]`）维度落在 IsArray 上
        }

        private ExprType InferExpressionType(ASTNode node)
        {
            /* 逗号表达式的类型 = **右边**的类型（整个表达式的值取右边） */
            if (node is CommaExpr commaNode)
            {
                return InferExpressionType(commaNode.Right);
            }
            if (node is CharLiteral)
            {
                return ExprType.Char;
            }
            if (node is NumberLiteral numLiteral)
            {
                // 根据后缀推断类型
                var suffix = numLiteral.Suffix ?? "";

                if (suffix.Contains('F') || suffix.Contains('f'))
                {
                    return ExprType.Float;
                }

                if (numLiteral.Value is float)
                {
                    return ExprType.Float;
                }
                if (numLiteral.Value is double)
                {
                    return ExprType.Double;
                }

                // 根据后缀推断整数类型
                bool isUnsigned = suffix.Contains('U') || suffix.Contains('u');
                bool isLong     = suffix.Contains('L') || suffix.Contains('l');

                if (isUnsigned && isLong)
                    return ExprType.UnsignedLong;
                else if (isUnsigned)
                    return ExprType.UnsignedInt;
                else if (isLong)
                    return ExprType.Long;
                else
                    return ExprType.Int;
            }
            if (node is BinaryOp binOp)
            {
                var leftType  = InferExpressionType(binOp.Left);
                var rightType = InferExpressionType(binOp.Right);

                // 指针算术：指针 + 整数 或 整数 + 指针 => 指针类型
                if (IsPointerType(leftType) && IsIntegerType(rightType))
                    return leftType;
                if (IsIntegerType(leftType) && IsPointerType(rightType))
                    return rightType;
                // 指针 - 指针 => 整数 (ptrdiff_t)
                if (IsPointerType(leftType) && IsPointerType(rightType))
                    return ExprType.Int;

                // 如果任一操作数是浮点，结果为浮点
                if (leftType == ExprType.Float || rightType == ExprType.Float)
                    return ExprType.Float;
                if (leftType == ExprType.Double || rightType == ExprType.Double)
                    return ExprType.Double;

                // 整数类型提升：根据C标准进行类型提升
                return PromoteIntegerTypes(leftType, rightType);
            }
            if (node is UnaryOp unaryOp)
            {
                // 取地址运算符 &，返回指针类型
                if (unaryOp.Op == "&")
                {
                    var operandType = InferExpressionType(unaryOp.Operand);
                    // 转换为对应的指针类型
                    switch (operandType)
                    {
                        case ExprType.Char: return ExprType.CharPtr;
                        case ExprType.Short: return ExprType.ShortPtr;
                        case ExprType.Int: return ExprType.IntPtr;
                        case ExprType.Long: return ExprType.LongPtr;
                        case ExprType.Float: return ExprType.FloatPtr;
                        case ExprType.Double: return ExprType.DoublePtr;
                        default: return ExprType.IntPtr;
                    }
                }
                // 解引用运算符 *，返回指向的类型
                if (unaryOp.Op == "*")
                {
                    /* ⚠ 操作数是**多星声明**的标识符时（`char **p` / `char *rows[]`），
                       `ExprType` 这一档**表达不了"指针的指针"** —— `StringToExprType`
                       把 `char **` 也归成 `CharPtr`。照下面的 `case CharPtr: return Char`
                       走，`*p` 被判成 `char` ⇒ 按**字节**加载：只读到指针地址的最低一个字节。

                       实测症状（`cases/23` 的 `**pp`）：结果是 **0**，
                       而 `pp[0][0]` 那条路（走 `Indices`）是对的 ——
                       同一个 `char **`，两条路径两种结论 ⇒ 判据回到**声明原文的星号数**，
                       与 `ElementIsPointer` 同源（那个函数记的三处共用里就有这一处）。

                       解一层后**仍是指针**：`char **p` 的 `*p` 是 `char*`，
                       所以类型档取同一个（`ExprType` 没有两级指针这一档）。 */
                    if (unaryOp.Operand is Identifier derefId && ElementIsPointer(derefId.Name))
                        return GetVarExprType(derefId.Name);

                    var operandType = InferExpressionType(unaryOp.Operand);
                    switch (operandType)
                    {
                        case ExprType.CharPtr: return ExprType.Char;
                        case ExprType.ShortPtr: return ExprType.Short;
                        case ExprType.IntPtr: return ExprType.Int;
                        case ExprType.LongPtr: return ExprType.Long;
                        case ExprType.FloatPtr: return ExprType.Float;
                        case ExprType.DoublePtr: return ExprType.Double;
                        case ExprType.VoidPtr: return ExprType.Int;
                        default: return ExprType.Int;
                    }
                }
                return InferExpressionType(unaryOp.Operand);
            }
            if (node is Identifier ident)
            {
                // 从符号表获取变量类型
                if (variableTypes.TryGetValue(ident.Name, out var type))
                    return type;
                // 枚举常量
                if (enumValues.ContainsKey(ident.Name))
                    return ExprType.Int;
                // 全局变量检查（简化：默认整数）
                if (dataSection.ContainsKey(ident.Name))
                    return ExprType.Int;
                // 函数名退化为函数指针 (void* 或 int*)
                if (ast.Functions.Exists(f => f.Name == ident.Name))
                    return ExprType.IntPtr;
                return ExprType.Unknown;
            }
            // 其他节点类型（如ArrayAccess、FunctionCall等）
            if (node is SizeOfNode)
                return ExprType.Int;
            if (node is ConditionalOp condOp)
            {
                // 三元运算符的结果类型是true和false分支的公共类型
                var trueType = InferExpressionType(condOp.TrueExpr);
                var falseType = InferExpressionType(condOp.FalseExpr);
                
                if (trueType == ExprType.Float || falseType == ExprType.Float)
                    return ExprType.Float;
                if (trueType == ExprType.Double || falseType == ExprType.Double)
                    return ExprType.Double;

                return PromoteIntegerTypes(trueType, falseType);
            }
            if (node is CastExpr castExpr)
            {
                // 类型转换表达式的结果类型是目标类型
                return StringToExprType(castExpr.Type);
            }
            if (node is StringLiteral)
            {
                return ExprType.CharPtr;
            }
            if (node is ArrayAccess arrAcc && arrAcc.Array is Identifier arrId)
            {
                // 从数组/指针类型推断元素类型。**局部与全局都要看** —— 只查 variableTypes
                // （它只装局部变量）的话，全局数组会落到 `return ExprType.Int`，
                // 于是 `char g[8]` 的 `g[0]` 按 **32 位** 读写（见 GetVarExprType 的注释）。
                var arrType = GetVarExprType(arrId.Name);
                if (IsPointerType(arrType))
                {
                    // ⚠ **指针数组**（`char *rows[]`）：元素**本身就是指针**，就是 `arrType`。
                    //
                    // `StringToExprType` 会先把 `[]` 剥掉再看 `*` ⇒ 这种声明的 arrType 已经是
                    // `CharPtr`，而下面那套是"**解一层引用**"（`char *p; p[0]` 该得 char）——
                    // 照它走就把元素判成了 `Char`，于是数组下标按**字节**读写
                    // （`moveb` + `sextb`）：读指针只读到地址的**最低一个字节**。
                    // 实测症状：`char *rows[]={"abc","def"}` 的 `rows[0]` 得到 `(null)`
                    // —— 而 nyancat 的帧数组、`argv` 那类全是这个形状。
                    //
                    // 判据看**声明的原文**（`*` 是否出现在 `[` 之前），不看已经剥过维度的 ExprType
                    // —— 剥完就再也分不出 `char *p[]` 与 `char **p` 的区别了。
                    // ⚠ **多级下标要按级数继续解引用。**
                    //
                    // 解析器把 `p[i][j]` 收成**一个** `ArrayAccess` + `Indices=[i,j]`
                    // （不是嵌套节点 —— 见 `Parser.Expressions.cs` 收集 `indices` 那段；
                    // 只有 `(p[i])[j]` 那种带括号的才会分成两层）。
                    // 所以这里**看不到"外层下标"**：只按"元素是指针"返回 `arrType` 的话，
                    // `pp[0][0]` 被判成 `CharPtr` ⇒ 最后一跳按 **4 字节**读。
                    //
                    // 症状极具迷惑性：**地址那侧是对的**（步长 4 再 1），只有最后取值的
                    // 宽度错了 ⇒ `pp[0][0]` 读成 `0x0A004241`（"AB\0\n"）而不是 65。
                    // 而 `%s` 打印**看着正常**（它走地址、不过元素类型推断）⇒ 只有
                    // `%d`/`%c` 把字符当数读才露馅。砸掉的是 `argv[i][0]`、`getopt`、
                    // 一切字符串表 —— 全是老程序的常见写法。
                    // 判据：`scripts/vml-c-probe/cases/23-charpp-subscript.c`。
                    var elemTy = ElementIsPointer(arrId.Name)
                        ? arrType                       // 元素本身就是指针（`char *rows[]` / `char **p`）
                        // char* → char, int* → int（单个指针的 `p[i]`）
                        : arrType switch
                        {
                            ExprType.CharPtr => ExprType.Char,
                            ExprType.ShortPtr => ExprType.Short,
                            ExprType.IntPtr => ExprType.Int,
                            ExprType.LongPtr => ExprType.Long,
                            ExprType.FloatPtr => ExprType.Float,
                            ExprType.DoublePtr => ExprType.Double,
                            ExprType.VoidPtr => ExprType.Char,
                            _ => ExprType.Int
                        };

                    // 每多一级下标就再解一层引用（`pp[0][0]`：`CharPtr` → `Char`）。
                    // 解到不是指针为止 —— `T *p; p[0][0]` 这种越界写法不该再往下解。
                    //
                    // ⚠⚠ **"多一级"要扣掉数组自己的维度数**：数组的下标走**维度**、不解引用，
                    //   只有**指针**的下标才解。按"下标数 - 1"一刀切，二维指针数组
                    //   （`char *bs[2][3]`）会被多解一层 ⇒ `bs[i][j]` 判成 `char`
                    //   ⇒ 末次取值按 1 字节读、且基址取成"元素里那个指针"。
                    //   实测 `bs[0][0]` 读出 `97`（`'a'`）、`%s` 打出空串 ——
                    //   而**一维的 `char *rows[]` 恰好落在正确的一侧**，所以这个缺陷
                    //   只在二维上冒头（`sl` 的整车图形表、菜单表、`argv` 那类全是二维）。
                    //   判据：`scripts/vml-c-probe/cases/33-mdim-pointer-array.c`。
                    int dims = DeclaredArrayDims(arrId.Name);
                    int extraDerefs = arrAcc.Indices.Count - (dims > 0 ? dims : 1);
                    for (int k = 0; k < extraDerefs && IsPointerType(elemTy); k++)
                        elemTy = DerefExprType(elemTy);
                    return elemTy;
                }
                return arrType; // 数组元素类型
            }
            if (node is ArrayAccess arrAcc2 && arrAcc2.Array is MemberAccess memberArr)
            {
                // 结构体/联合体成员数组访问，如 u.s[0]
                string structType = GetStructTypeName(memberArr.Object);
                string memberTypeStr = GetMemberType(structType, memberArr.MemberName);
                if (!string.IsNullOrEmpty(memberTypeStr))
                    return StringToExprType(memberTypeStr);
                return ExprType.Int;
            }
            if (node is ArrayAccess arrAcc3 && arrAcc3.Array is UnaryOp unaryBase && unaryBase.Op == "*")
            {
                // (*ptr)[idx] — 解引用指针后下标访问，返回指针所指元素类型
                var ptrType = InferExpressionType(unaryBase.Operand);
                return ptrType switch
                {
                    ExprType.CharPtr => ExprType.Char,
                    ExprType.ShortPtr => ExprType.Short,
                    ExprType.IntPtr => ExprType.Int,
                    ExprType.LongPtr => ExprType.Long,
                    ExprType.FloatPtr => ExprType.Float,
                    ExprType.DoublePtr => ExprType.Double,
                    ExprType.VoidPtr => ExprType.Char,
                    _ => ExprType.Int
                };
            }
            if (node is ArrayAccess arrAcc4 && arrAcc4.Array is ArrayAccess innerArr)
            {
                // 嵌套下标访问 `x[i][j]`：**最后那一层下标解掉的是"内层元素的引用"**。
                //
                // ⚠ 不能直接返回内层的类型：内层是**指针**时（`char **fr` 的 `fr[i]`、
                //   `char *rows[]` 的 `rows[i]`），`fr[i][j]` 是那个指针**指向的**字符，
                //   而 `fr[i]` 的类型仍是 `CharPtr` ⇒ 拿它去定步长会按 4 走，
                //   相邻两格错开 4 字节（实测 `rows[1][1]` 直接读到串尾之外，打印成空）。
                var innerTy = InferExpressionType(innerArr);
                return IsPointerType(innerTy) ? DerefExprType(innerTy) : innerTy;
            }
            if (node is MemberAccess memberAcc)
            {
                string structTypeName2 = GetStructTypeName(memberAcc.Object);
                string memberTypeStr2 = GetMemberType(structTypeName2, memberAcc.MemberName);
                if (!string.IsNullOrEmpty(memberTypeStr2))
                {
                    // 数组成员退化为指针
                    if (IsArrayMember(structTypeName2, memberAcc.MemberName))
                        memberTypeStr2 += "*";
                    return StringToExprType(memberTypeStr2);
                }
                return ExprType.Int;
            }
            if (node is UnaryOp)
            {
                return ExprType.Int;
            }
            if (node is FunctionCall funcCall)
            {
                var funcRetType = GetFunctionReturnType(funcCall.Name);
                return StringToExprType(funcRetType);
            }
            return ExprType.Unknown;
        }

        /// <summary>
        /// 根据C标准进行整数类型提升
        /// </summary>
        private ExprType PromoteIntegerTypes(ExprType type1, ExprType type2)
        {
            // 如果两个类型相同，直接返回
            if (type1 == type2)
                return type1;

            // 定义类型等级（从低到高）
            var typeRank = new Dictionary<ExprType, int>
            {
                { ExprType.Char, 1 },
                { ExprType.UnsignedChar, 2 },
                { ExprType.Short, 3 },
                { ExprType.UnsignedShort, 4 },
                { ExprType.Int, 5 },
                { ExprType.UnsignedInt, 6 },
                { ExprType.Long, 7 },
                { ExprType.UnsignedLong, 8 },
                { ExprType.LongLong, 9 },
                { ExprType.UnsignedLongLong, 10 }
            };

            // 如果有一个类型不在等级表中（如Void、Float等），返回Int作为默认
            if (!typeRank.ContainsKey(type1) || !typeRank.ContainsKey(type2))
                return ExprType.Int;

            // 获取类型等级
            var rank1 = typeRank[type1];
            var rank2 = typeRank[type2];

            // 选择等级较高的类型
            var promotedType = rank1 > rank2 ? type1 : type2;

            // C标准整数提升规则：
            // 1. 如果两个操作数都是有符号或无符号，但大小不同，提升到较大的类型
            // 2. 如果一个操作数是无符号且等级不低于另一个有符号操作数，提升到无符号类型
            // 3. 否则，提升到有符号类型
            
            // 检查是否有符号性差异
            bool isType1Unsigned = type1 == ExprType.UnsignedChar || type1 == ExprType.UnsignedShort ||
                                   type1 == ExprType.UnsignedInt || type1 == ExprType.UnsignedLong ||
                                   type1 == ExprType.UnsignedLongLong;
            bool isType2Unsigned = type2 == ExprType.UnsignedChar || type2 == ExprType.UnsignedShort ||
                                   type2 == ExprType.UnsignedInt || type2 == ExprType.UnsignedLong ||
                                   type2 == ExprType.UnsignedLongLong;
            
            // 如果符号性相同，返回等级较高的类型
            if (isType1Unsigned == isType2Unsigned)
                return promotedType;
            
            // 符号性不同，应用C标准规则
            if (isType1Unsigned && rank1 >= rank2)
            {
                // 类型1是无符号且等级不低于类型2，提升到无符号类型
                return type1;
            }
            else if (isType2Unsigned && rank2 >= rank1)
            {
                // 类型2是无符号且等级不低于类型1，提升到无符号类型
                return type2;
            }
            else
            {
                // 否则提升到有符号类型
                // 找到对应的有符号类型
                if (isType1Unsigned)
                {
                    // 类型1是无符号，返回类型2（有符号）
                    return type2;
                }
                else
                {
                    // 类型2是无符号，返回类型1（有符号）
                    return type1;
                }
            }
        }

    }
}  // namespace
